 function challengeControls(id,label){const gate=challengeAvailability(id),action=id==='ice-breaker'?'challenge':'goto-dodgeball',resource='challenge:'+id;return `<div class="challenge-access"><span id="access-${id}" class="challenge-lock ${gate.enabled?'available':'locked'}">${worldIcon(gate.enabled?'shield':'lock')}<span>${gate.enabled?'RETO ABIERTO':'CERRADO POR STAFF'}</span></span>${!gate.enabled?'<p class="challenge-access-note">La dirección decide cuándo comienza esta prueba.</p>':''}<button class="yellow-button" data-action="${action}" aria-describedby="access-${id}" ${gate.canPlay?'':'disabled'}>${gate.canPlay?(gate.enabled?'ENTRAR A '+label:'VISTA PREVIA · DIRECCIÓN'):'ESPERANDO APERTURA'}${worldIcon(gate.enabled?'arrow':'lock')}</button>${state.permissions.direct?`<button class="challenge-direct-toggle small-button" data-access="${resource}" data-enabled="${gate.enabled}" aria-pressed="${gate.enabled}" aria-label="${gate.enabled?'Cerrar':'Abrir'} ${label} para participantes">${worldIcon(gate.enabled?'lock':'shield')} ${gate.enabled?'CERRAR RETO':'ABRIR RETO'}<span>SOLO DIRECCIÓN</span></button>`:''}</div>`;}
